// Copyright 2026 The Gitea Authors. All rights reserved.
// SPDX-License-Identifier: MIT

// Package ar implements a minimal reader and writer for the common ar archive format
// as used by Debian packages. It is derived from github.com/blakesmith/ar
// (Copyright (c) 2013 Blake Smith, MIT license), hardened against malformed headers.
package ar

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"strconv"
	"time"
)

const (
	headerByteSize = 60
	globalHeader   = "!<arch>\n"
)

var (
	ErrWriteTooLong = errors.New("ar: write too long")
	ErrInvalidSize  = errors.New("ar: invalid member size")
)

type Header struct {
	Name    string
	ModTime time.Time
	Uid     int
	Gid     int
	Mode    int64
	Size    int64
}

// Reader provides sequential read access to an ar archive.
type Reader struct {
	r   io.Reader
	nb  int64
	pad int64
	err error
}

// NewReader creates a Reader. The global ar header is consumed lazily on the first call to Next.
func NewReader(r io.Reader) *Reader {
	return &Reader{r: r, pad: -1}
}

func trimField(b []byte) string {
	return string(bytes.TrimRight(b, " "))
}

func parseNumeric(b []byte, base int) (int64, error) {
	s := trimField(b)
	if s == "" {
		return 0, nil
	}
	return strconv.ParseInt(s, base, 64)
}

func (rd *Reader) skipUnread() error {
	skip := rd.nb + rd.pad
	rd.nb, rd.pad = 0, 0
	if skip <= 0 {
		return nil
	}
	_, err := io.CopyN(io.Discard, rd.r, skip)
	return err
}

// Next advances to the next entry in the archive.
func (rd *Reader) Next() (*Header, error) {
	if rd.err != nil {
		return nil, rd.err
	}
	hdr, err := rd.next()
	if err != nil {
		rd.err = err
	}
	return hdr, err
}

func (rd *Reader) next() (*Header, error) {
	if rd.pad < 0 { // first call: strip the global header
		rd.pad = 0
		magic := make([]byte, len(globalHeader))
		if _, err := io.ReadFull(rd.r, magic); err != nil {
			if err == io.ErrUnexpectedEOF {
				err = io.EOF
			}
			return nil, err
		}
		if string(magic) != globalHeader {
			return nil, errors.New("ar: invalid archive header")
		}
	}
	if err := rd.skipUnread(); err != nil {
		return nil, err
	}

	buf := make([]byte, headerByteSize)
	if _, err := io.ReadFull(rd.r, buf); err != nil {
		return nil, err
	}
	if buf[58] != '`' || buf[59] != '\n' {
		return nil, errors.New("ar: invalid header terminator")
	}

	hdr := new(Header)
	hdr.Name = trimField(buf[0:16])
	modTime, err := parseNumeric(buf[16:28], 10)
	if err != nil {
		return nil, fmt.Errorf("ar: invalid mtime: %w", err)
	}
	hdr.ModTime = time.Unix(modTime, 0)
	uid, err := parseNumeric(buf[28:34], 10)
	if err != nil {
		return nil, fmt.Errorf("ar: invalid uid: %w", err)
	}
	hdr.Uid = int(uid)
	gid, err := parseNumeric(buf[34:40], 10)
	if err != nil {
		return nil, fmt.Errorf("ar: invalid gid: %w", err)
	}
	hdr.Gid = int(gid)
	if mode := trimField(buf[40:48]); len(mode) > 3 {
		if hdr.Mode, err = strconv.ParseInt(mode[3:], 8, 64); err != nil {
			return nil, fmt.Errorf("ar: invalid mode: %w", err)
		}
	}
	size, err := parseNumeric(buf[48:58], 10)
	if err != nil || size < 0 {
		return nil, ErrInvalidSize
	}
	hdr.Size = size

	rd.nb = size
	rd.pad = size % 2
	return hdr, nil
}

// Read reads from the current entry in the archive.
func (rd *Reader) Read(b []byte) (int, error) {
	if rd.nb <= 0 {
		return 0, io.EOF
	}
	if int64(len(b)) > rd.nb {
		b = b[:rd.nb]
	}
	n, err := rd.r.Read(b)
	rd.nb -= int64(n)
	return n, err
}

// Writer provides sequential writing of an ar archive.
type Writer struct {
	w  io.Writer
	nb int64
}

func NewWriter(w io.Writer) *Writer { return &Writer{w: w} }

func (aw *Writer) WriteGlobalHeader() error {
	_, err := io.WriteString(aw.w, globalHeader)
	return err
}

func padField(s string, n int) []byte {
	b := bytes.Repeat([]byte{' '}, n)
	copy(b, s)
	return b
}

// WriteHeader writes the header and prepares to receive hdr.Size bytes of payload.
func (aw *Writer) WriteHeader(hdr *Header) error {
	aw.nb = hdr.Size
	buf := make([]byte, 0, headerByteSize)
	buf = append(buf, padField(hdr.Name, 16)...)
	buf = append(buf, padField(strconv.FormatInt(hdr.ModTime.Unix(), 10), 12)...)
	buf = append(buf, padField(strconv.Itoa(hdr.Uid), 6)...)
	buf = append(buf, padField(strconv.Itoa(hdr.Gid), 6)...)
	buf = append(buf, padField("100"+strconv.FormatInt(hdr.Mode, 8), 8)...)
	buf = append(buf, padField(strconv.FormatInt(hdr.Size, 10), 10)...)
	buf = append(buf, '`', '\n')
	_, err := aw.w.Write(buf)
	return err
}

// Write writes to the current entry; it returns ErrWriteTooLong if more than the declared size is written.
func (aw *Writer) Write(b []byte) (int, error) {
	var err error
	if int64(len(b)) > aw.nb {
		b = b[:aw.nb]
		err = ErrWriteTooLong
	}
	n, werr := aw.w.Write(b)
	aw.nb -= int64(n)
	if werr != nil {
		return n, werr
	}
	if len(b)%2 == 1 { // entries are aligned to an even byte
		n2, _ := aw.w.Write([]byte{'\n'})
		return n + n2, err
	}
	return n, err
}
