package ar

import (
	"bytes"
	"io"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestRoundTrip(t *testing.T) {
	var buf bytes.Buffer
	w := NewWriter(&buf)
	require.NoError(t, w.WriteGlobalHeader())
	files := []struct{ name, data string }{{"debian-binary", "2.0\n"}, {"control.tar", "odd"}, {"data.tar", "x"}}
	for _, f := range files {
		require.NoError(t, w.WriteHeader(&Header{Name: f.name, Mode: 0o600, Size: int64(len(f.data))}))
		_, err := w.Write([]byte(f.data))
		require.NoError(t, err)
	}

	r := NewReader(&buf)
	for _, f := range files {
		hdr, err := r.Next()
		require.NoError(t, err)
		assert.Equal(t, f.name, hdr.Name)
		assert.EqualValues(t, 0o600, hdr.Mode)
		data, err := io.ReadAll(r)
		require.NoError(t, err)
		assert.Equal(t, f.data, string(data))
	}
	_, err := r.Next()
	assert.ErrorIs(t, err, io.EOF)
}

func TestNegativeSize(t *testing.T) {
	hdr := "name" + strings.Repeat(" ", 12) + strings.Repeat(" ", 12) + "0     " + "0     " + "100600  " + "-5        " + "`\n"
	require.Len(t, hdr, headerByteSize)
	r := NewReader(strings.NewReader(globalHeader + hdr + "xxxxx"))
	_, err := r.Next()
	assert.ErrorIs(t, err, ErrInvalidSize)
}
